commit fab0f61a025f824f76980d54c3aa2cfa435a8c79
Author: Dan LaRocque <dalaro@hopcount.org>
Date:   Mon May 4 21:57:44 2015 -0400

    Bulkloader and Hadoop IO format config key changes

    BulkLoaderVertexProgram and the Hadoop Input/OutputFormats now use
    harmonized config key prefixes: titanmr.{ioformat,bulkload}.conf.
    Also added a ConfigElement.getPath overload that includes the root
    element name (the default behavior is still to exclude the root).

    This commit fixes some DEBUG logging statements needlessly emitted at
    ERROR.

    For #1045

diff --git a/titan-core/src/main/java/com/thinkaurelius/titan/diskstorage/configuration/ConfigElement.java b/titan-core/src/main/java/com/thinkaurelius/titan/diskstorage/configuration/ConfigElement.java
index 9a59f5f5b..2dede8f7b 100644
--- a/titan-core/src/main/java/com/thinkaurelius/titan/diskstorage/configuration/ConfigElement.java
+++ b/titan-core/src/main/java/com/thinkaurelius/titan/diskstorage/configuration/ConfigElement.java
@@ -131,6 +131,10 @@ public abstract class ConfigElement {
 //    }

     public static String getPath(ConfigElement element, String... umbrellaElements) {
+        return getPath(element, false, umbrellaElements);
+    }
+
+    public static String getPath(ConfigElement element, boolean includeRoot, String... umbrellaElements) {
         Preconditions.checkNotNull(element);
         if (umbrellaElements==null) umbrellaElements = new String[0];
         String path = element.getName();
@@ -147,6 +151,13 @@ public abstract class ConfigElement {
             path = parent.getName() + SEPARATOR + path;
             element = parent;
         }
+        if (includeRoot) {
+            // Assumes that roots are not umbrellas
+            // If roots could be umbrellas, we might have to change the interpretation of umbrellaElements
+            path = (element.isNamespace() ?
+                    element.getName() :
+                    element.getNamespace().getName()) + SEPARATOR + path;
+        }
         //Don't make this check so that we can still access more general config items
         Preconditions.checkArgument(umbrellaPos<0,"Found unused umbrella element: %s",umbrellaPos<0?null:umbrellaElements[umbrellaPos]);
         return path;

