29	    }
30	
31	    public Configuration getHadoopConfiguration() {
32	        return conf;
33	    }
34	
35	    public ModifiableConfiguration getTitanGraphConf() {
36	        return prefixView(GraphDatabaseConfiguration.ROOT_NS, TitanHadoopConfiguration.GRAPH_CONFIG_KEYS, this);
37	    }
38	}

